package at.heinz.deviceai.learning

import java.io.File
import java.io.FileOutputStream
import java.nio.file.Files
import java.nio.file.StandardCopyOption
import java.nio.file.AtomicMoveNotSupportedException
import at.heinz.deviceai.cognitive.CognitiveTraceCodec
import at.heinz.deviceai.cognitive.CognitiveTraceSnapshot
import at.heinz.deviceai.cognitive.TraceFeedback

/** Bounded metadata-only audit of outcomes, NOT text generated by local LLMs.
 * The dialogue does not become a user-confirmed fact through this journal.
 */
class ContinuumRuntimeEventJournal(private val appDirectory:File) {
    private val folder=File(appDirectory,"learning-core-v2")
    private val file=File(folder,"runtime-events-v1.tsv")

    data class Summary(val successes:Int,val failures:Int,val recent:List<String>)

    /** Same metadata journal directory, separate versioned rows; no learning ledger write. */
    fun recordTrace(trace:CognitiveTraceSnapshot) = traceTransaction {
        writeTraces((readTraces().filterNot { it.id==trace.id }+trace).takeLast(32))
    }
    fun traces():List<CognitiveTraceSnapshot> = traceTransaction { readTraces() }
    fun reviewTrace(id:String,feedback:TraceFeedback):Boolean = traceTransaction {
        val rows=readTraces()
        if(rows.none { it.id==id }) false else {
            writeTraces(rows.map { if(it.id==id) it.copy(feedback=feedback) else it });true
        }
    }
    private fun readTraces():List<CognitiveTraceSnapshot> {
        val target=File(folder,"turn-traces-v1.tsv")
        require(!java.nio.file.Files.isSymbolicLink(target.toPath()))
        if(!target.exists())return emptyList()
        require(target.length()<=270_000)
        val rows=target.readLines(Charsets.UTF_8).map(CognitiveTraceCodec::decode)
        require(rows.size<=32 && rows.map { it.id }.distinct().size==rows.size)
        return rows
    }
    private fun writeTraces(rows:List<CognitiveTraceSnapshot>) {
        val pending=File.createTempFile("turn-traces-",".tmp",folder)
        try {
            FileOutputStream(pending).use { out ->
                out.write(rows.joinToString("\n",postfix="\n") { CognitiveTraceCodec.encode(it) }.toByteArray(Charsets.UTF_8));out.fd.sync()
            }
            Files.move(pending.toPath(),File(folder,"turn-traces-v1.tsv").toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING)
        } finally {pending.delete()}
    }
    private fun <T> traceTransaction(action:()->T):T = synchronized(TRACE_MONITOR) {
        require(!Files.isSymbolicLink(appDirectory.toPath()) && !Files.isSymbolicLink(folder.toPath()))
        check(folder.isDirectory || folder.mkdirs())
        java.nio.channels.FileChannel.open(File(folder,".trace.lock").toPath(),
            java.nio.file.StandardOpenOption.CREATE,java.nio.file.StandardOpenOption.WRITE,
            java.nio.file.LinkOption.NOFOLLOW_LINKS).use { channel -> channel.lock().use { action() } }
    }
    companion object { private val TRACE_MONITOR=Any() }

    @Synchronized fun recordLocalOutcome(success:Boolean,at:Long=System.currentTimeMillis()) {
        require(at>=0)
        val event=at.toString()+"\t"+if(success)"LOCAL_MODEL_OK" else "LOCAL_MODEL_FAILED"
        val old=read().recent
        val entries=(old+event).takeLast(16)
        require(entries.joinToString("\n").length<1500)
        if(!folder.exists())check(folder.mkdirs())
        val pending=File.createTempFile("runtime-events-",".tmp",folder)
        try {
            FileOutputStream(pending).use {
                it.write(entries.joinToString("\n",postfix="\n").toByteArray(Charsets.UTF_8))
                it.fd.sync()
            }
            try {
                Files.move(pending.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,
                    StandardCopyOption.REPLACE_EXISTING)
            } catch(_:AtomicMoveNotSupportedException) {
                Files.move(pending.toPath(),file.toPath(),StandardCopyOption.REPLACE_EXISTING)
            }
        } finally { pending.delete() }
    }

    @Synchronized fun read():Summary {
        if(!file.exists())return Summary(0,0,emptyList())
        require(file.length() in 0..1500) { "Invalid runtime event ledger size" }
        val records=file.readLines(Charsets.UTF_8).filter(String::isNotBlank)
        require(records.size<=16)
        for(record in records) {
            val parts=record.split('\t')
            require(parts.size==2 && parts[0].toLongOrNull()!=null &&
                parts[1] in setOf("LOCAL_MODEL_OK","LOCAL_MODEL_FAILED")) {
                "Invalid runtime event ledger row"
            }
        }
        return Summary(records.count { it.endsWith("LOCAL_MODEL_OK") },
            records.count { it.endsWith("LOCAL_MODEL_FAILED") },records)
    }
}
